cd /tmp && node -e '
const Y=require("/usr/share/nodejs/yaml"); const fs=require("fs");
for (const f of ["events-sample.yaml","fixtures-users.yml","audit-log.yaml"]) {
  const lines=fs.readFileSync("/tmp/corpus/yaml/"+f,"utf8").split("\n").filter(l=>l.length);
  let ok=0, json=0;
  for (const l of lines) {
    const d=Y.parseDocument(l,{strict:true});
    if(!d.errors.length && Y.isMap(d.contents) && d.contents.flow) ok++; else console.log("bad line in",f,":",d.errors.map(String));
    try{JSON.parse(l);json++}catch{}
  }
  console.log(f, "lines:",lines.length,"valid one-line flow maps:",ok,"also strict JSON:",json);
}'

