cd /tmp && node -e '
const Y=require("/usr/share/nodejs/yaml"); const JY=require("/usr/share/nodejs/js-yaml"); const fs=require("fs"); const path=require("path");
const jsonl=new Set(["events-sample.yaml","fixtures-users.yml","audit-log.yaml"]);
let bad=0;
function jsSchemaFor(src){
  const tags=new Set(); const re=/(?:^|[\s\[{,])(!!?[^\s,\[\]{}]+)/gm; let m;
  while((m=re.exec(src))) tags.add(m[1]);
  const types=[];
  for (const t of tags){ const full=t.startsWith("!!")?"tag:yaml.org,2002:"+t.slice(2):t; for (const kind of ["scalar","sequence","mapping"]) types.push(new JY.Type(full,{kind,construct:d=>d})); }
  return JY.DEFAULT_SCHEMA.extend(types);
}
const dir="/tmp/corpus/yaml";
for (const f of fs.readdirSync(dir).sort()) {
  const src=fs.readFileSync(path.join(dir,f),"utf8");
  const units = jsonl.has(f) ? src.split("\n").filter(Boolean) : [src];
  for (const u of units){
    const docs=Y.parseAllDocuments(u,{strict:true,uniqueKeys:true});
    const errs=[].concat(...docs.map(d=>d.errors));
    if(errs.length){bad++;console.log("eemeli ERR",f,errs[0].message.split("\n")[0]);}
    try{ JY.loadAll(u,()=>{},{schema:jsSchemaFor(u)}); }catch(e){bad++;console.log("js-yaml ERR",f,e.message.split("\n")[0]);}
    let multi=0; for(const d of docs) Y.visit(d,{Collection(k,n){ if(n.flow&&n.range&&u.slice(n.range[0],n.range[1]).includes("\n")) multi++; }});
    if(multi) console.log("multi-line flow collections:",f,multi);
  }
}
console.log("yaml problems:",bad);
'

