const Y=require("/usr/share/nodejs/yaml"); const fs=require("fs"); const path=require("path");
let n=0, bad=0;
function check(label, text){ n++; const d=Y.parseDocument(text,{strict:true,uniqueKeys:true}); if(d.errors.length){bad++; console.log("ERR",label,d.errors[0].message.split("\n")[0]); } }
// front matter
for (const f of fs.readdirSync("/tmp/corpus/md").sort()) {
  const src=fs.readFileSync("/tmp/corpus/md/"+f,"utf8"); const L=src.split("\n");
  if (L[0]==="---") { const end=L.indexOf("---",1); check(f+" front-matter", L.slice(1,end).join("\n")); }
}
// hashpipe blocks: consecutive lines starting with optional indent + "#|"
function hashpipes(file, src){
  const L=src.split("\n"); let blk=[], start=0; const out=[];
  const flush=()=>{ if(blk.length){ out.push([start,blk.join("\n")]); blk=[]; } };
  L.forEach((l,i)=>{ const m=l.match(/^\s*#\|(.*)$/); if(m){ if(!blk.length) start=i+1; blk.push(m[1].startsWith(" ")?m[1].slice(1):m[1]); } else flush(); });
  flush(); return out;
}
const blocks={};
for (const d of ["md","py","r"]) for (const f of fs.readdirSync("/tmp/corpus/"+d).sort()) {
  const src=fs.readFileSync(path.join("/tmp/corpus",d,f),"utf8");
  for (const [line,text] of hashpipes(f,src)) { check(d+"/"+f+":"+line+" #|", text); blocks[d]=(blocks[d]||0)+1; }
}
console.log("checked",n,"yaml snippets; errors:",bad, "hashpipe blocks per dir:", JSON.stringify(blocks));
'
